'use strict';
const D=window.RESEARCH,F=window.Forecast,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const percent=(x,exact=false)=>(100*x).toFixed(exact?1:0)+'%';
const signed=x=>(x>0?'+':'')+percent(x);
const source=id=>D.sources.find(s=>s.id===id);
const storageKey='structural-futures-plan-v2';
let plan=F.baseline(D),loadNote='',toastTimer,lastFocus;
try{const raw=new URL(location.href).searchParams.get('plan');if(raw){if(raw.length>12000)throw Error('Shared scenario is too large.');plan=F.validateSnapshot(D,JSON.parse(raw));loadNote='Shared scenario loaded.';}else{const saved=localStorage.getItem(storageKey);if(saved){plan=F.validateSnapshot(D,JSON.parse(saved));loadNote='Your saved workload has been restored.';}}}catch{loadNote='The saved or shared scenario could not be read. The baseline is shown.';}
const ui={taskQuery:'',taskTag:'All',taskSort:'workflow',sourceQuery:'',sourceKind:'All',evidenceFilter:'All'};
const totalHours=()=>Math.round(Object.values(plan.hours).reduce((a,b)=>a+b,0)*100)/100;
const options=()=>({potentialScale:plan.potentialScale,adoptionScale:plan.adoptionScale,overheadDelta:plan.overheadDelta});
const estimate=(scenario=plan.scenario,h=plan.horizon)=>F.estimate(D,scenario,h,plan.hours,options());
const range=(scenario=plan.scenario,h=plan.horizon)=>F.envelope(D,scenario,h,plan.hours,options());
const scenario=()=>D.scenarios.find(s=>s.id===plan.scenario);
const profileName=()=>D.profiles.find(p=>p.id===plan.profile)?.name||'Custom workload';
function refs(ids=[],assumed=false){return `<div class="citations">${assumed?'<a class="assumption-link" href="#methods">A01 · author assumptions</a><span class="citation-label"> · Context:</span>':'<span class="citation-label">Evidence:</span>'}${[...new Set(ids)].map(id=>`<a class="cite" href="#references/${id}" data-source="${id}" aria-label="Inspect source ${id}: ${esc(source(id)?.title||id)}">${id}</a>`).join('')}</div>`;}
const badge=(label,type='assumption')=>`<span class="badge ${type}">${label}</span>`;
const heading=(k,title,description)=>`<div class="page-heading"><div class="eyebrow">${k}</div><h1>${title}</h1><p>${description}</p></div>`;
function horizonTabs(){return `<div class="horizon-tabs" aria-label="Forecast horizon">${D.horizons.map((y,i)=>`<button data-horizon="${i}" aria-pressed="${i===plan.horizon}">${y}<small>${i?'+'+(y-2026)+' years':'baseline'}</small></button>`).join('')}</div>`;}
function scenarioButtons(){return `<div class="scenario-select" aria-label="Technology scenario">${D.scenarios.map((s,i)=>`<button class="scenario-button" data-scenario="${s.id}" aria-pressed="${s.id===plan.scenario}"><span class="scenario-index">0${i+1} / ${i===3?'STRESS CASE':i===1?'WORKING CASE':i===0?'SLOWER PATH':'FASTER PATH'}</span><strong>${s.name}</strong><small>${['Uneven, limited adoption','Connected, supervised workflows','Broad digital substitution','Retreat, review costs, recovery'][i]}</small></button>`).join('')}</div>`;}
function marker(shape,x,y,color,size=4){if(shape==='square')return `<rect x="${x-size}" y="${y-size}" width="${size*2}" height="${size*2}" fill="${color}"/>`;if(shape==='diamond')return `<path d="M${x},${y-size-1}l${size+1},${size+1}l-${size+1},${size+1}l-${size+1},-${size+1}Z" fill="${color}"/>`;if(shape==='triangle')return `<path d="M${x},${y-size-1}l${size+1},${size*2+1}h-${size*2+2}Z" fill="${color}"/>`;return `<circle cx="${x}" cy="${y}" r="${size}" fill="${color}"/>`;}
function chart(){const W=760,H=295,L=43,R=28,T=20,B=42,series=D.scenarios.map(s=>({s,values:D.horizons.map((_,i)=>estimate(s.id,i).net)}));const min=Math.min(-.1,...series.flatMap(s=>s.values)),max=1,x=yr=>L+(yr-2026)/30*(W-L-R),y=v=>T+(max-v)/(max-min)*(H-T-B);
let svg=`<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Four conditional paths for additional fixed-scope labor savings, with distinct line patterns and point shapes. Exact values are in the table below.">`;
for(const tick of [0,.25,.5,.75,1])svg+=`<line x1="${L}" x2="${W-R}" y1="${y(tick)}" y2="${y(tick)}" stroke="var(--line)"/><text x="${L-8}" y="${y(tick)+4}" fill="var(--muted)" text-anchor="end" font-size="11">${tick*100}%</text>`;
D.horizons.forEach(yr=>svg+=`<text x="${x(yr)}" y="${H-10}" fill="var(--muted)" text-anchor="middle" font-size="11">${yr}</text>`);
svg+=`<line x1="${x(D.horizons[plan.horizon])}" x2="${x(D.horizons[plan.horizon])}" y1="${T}" y2="${H-B}" stroke="var(--accent)" opacity=".3" stroke-dasharray="3 5"/>`;
for(const {s,values} of series){svg+=`<polyline points="${values.map((v,i)=>x(D.horizons[i])+','+y(v)).join(' ')}" fill="none" stroke="${s.color}" stroke-width="${s.id===plan.scenario?3.2:2}" stroke-dasharray="${s.dash}"/>`;values.forEach((v,i)=>{const px=x(D.horizons[i]),py=y(v),label=s.name+' · '+D.horizons[i]+' · '+percent(v)+' additional hours removed';svg+=`<g class="data-point" role="button" tabindex="0" aria-label="${esc(label)}" data-point="${s.id},${i}"><circle class="point-ring" cx="${px}" cy="${py}" r="13" fill="transparent"/>${marker(s.marker,px,py,s.color,i===plan.horizon?5:4)}<title>${esc(label)}</title></g>`;});}
return svg+'</svg>';}
function chartFigure(){return `<figure>${chart()}<div class="chart-key">${D.scenarios.map(s=>`<span><svg viewBox="0 0 24 10" aria-hidden="true"><line x1="0" y1="5" x2="24" y2="5" stroke="${s.color}" stroke-width="2" stroke-dasharray="${s.dash}"/></svg>${s.name}</span>`).join('')}</div><div class="chart-note" id="chart-note" aria-live="polite">${scenario().name} · <b>${D.horizons[plan.horizon]}: ${percent(estimate().net)}</b> additional hours removed. Tap a point to inspect.</div><figcaption>Conditional model paths for the selected workload and assumptions. Lines connect modeled horizons; they are not year-by-year forecasts. Negative savings mean added labor. ${refs(['S05','S13','S15','S17','S20'],true)}</figcaption></figure>`;}
function snapshotTable(){return `<details class="block"><summary>Inspect all calculated values</summary><div class="table-wrap"><table><thead><tr><th>Scenario</th>${D.horizons.slice(1).map(y=>`<th>${y}</th>`).join('')}</tr></thead><tbody>${D.scenarios.map(s=>`<tr><th scope="row">${s.name}</th>${D.horizons.slice(1).map((_,i)=>`<td>${percent(estimate(s.id,i+1).net,true)}</td>`).join('')}</tr>`).join('')}</tbody><caption>Exact arithmetic under selected inputs. Decimal places are for reproducibility, not evidence of forecast precision. ${refs(['S13','S15'],true)}</caption></table></div></details>`;}
function overview(){const r=estimate(),e=range(),yr=D.horizons[plan.horizon];return `<section class="hero"><div><div class="eyebrow">THE WHOLE PROFESSION / 2026 → 2056</div><h1>The future of<br>structural <span class="accent">work.</span></h1><p>Explore how AI could change the work behind a structure—from load paths and calculations to BIM, site visits and professional judgment.</p><div class="actions"><a class="primary" href="#tasks">Explore the task atlas ↗</a><a href="#scenarios">Model my workload</a><a href="#evidence">Inspect the evidence</a></div></div><div class="hero-aside"><div class="eyebrow">THE WORKING HYPOTHESIS</div><h3 style="margin-top:12px">Less routine production.<br>More decisions to verify.</h3><p>My inference: repeatable digital delivery compresses first. Team size and employment depend on adoption, demand and the work created around it.</p><button class="text-button" data-claim="thesis">Why this conclusion? →</button>${refs(['S03','S13','S15','S24'],true)}</div></section>
<div class="horizon-bar"><div><div class="eyebrow">CHOOSE A HORIZON</div><span class="compact quiet">${esc(profileName())} · ${esc(scenario().name)}</span></div>${horizonTabs()}</div>
<div class="grid four"><article class="card metric-card featured"><div class="eyebrow">MODELED NET SAVING</div><div class="metric">${percent(r.net)}</div><div class="stat-label">Additional hours removed by ${yr}</div><div class="stat-note">Same scope and quality · baseline 2026</div>${refs([],true)}</article><article class="card metric-card"><div class="eyebrow">ASSUMPTION RANGE</div><div class="metric">${Math.round(e.low*100)}–${Math.round(e.high*100)}<small>%</small></div><div class="stat-label">Sensitivity around this case</div><div class="stat-note">Chosen stress bounds; not confidence limits</div><button class="text-button" data-claim="range">See how the range is built →</button>${refs([],true)}</article><article class="card metric-card"><div class="eyebrow">THE FULL WORKFLOW</div><div class="metric">59 <small>tasks</small></div><div class="stat-label">Across 14 connected clusters</div><div class="stat-note">Engineering, BIM, field, management and QA</div>${refs(['S02','S03','S04'])}</article><article class="card metric-card"><div class="eyebrow">TRACEABLE RESEARCH</div><div class="metric">24 <small>sources</small></div><div class="stat-label">Evidence through 30 Sep 2026</div><div class="stat-note">Published findings, prototypes and limits</div><a class="text-button" href="#references">Open the source register →</a></article></div>
<div class="chart-layout block"><div class="card"><div class="section-head"><div><h2>Four paths. Different conditions.</h2><p>Additional labor hours removed per fixed-scope workload</p></div>${badge('Author scenarios')}</div>${chartFigure()}${snapshotTable()}</div><div class="card"><div class="section-head"><h2>What the evidence says</h2>${badge('Observed / reported','observed')}</div><div class="signal"><div class="signal-title"><span>Deployment is uneven</span><strong>45%</strong></div><p>RICS respondents reported no AI implementation in construction projects. Broader than structural design offices.</p>${refs(['S05'])}</div><div class="signal"><div class="signal-title"><span>Some bounded tasks compress</span><strong>~80%</strong></div><p>Time saving implied by Arup/YJK iteration endpoints. Company-reported; not a whole-project result.</p>${refs(['S20'])}</div><div class="signal"><div class="signal-title"><span>Production reliability is unresolved</span><strong>32%</strong></div><p>BIMgent success on an architectural modeling experiment. Not structural accuracy.</p>${refs(['S10'])}</div><a class="button-link" href="#evidence">Examine findings and limitations ↗</a></div></div>
<div class="notice"><strong>Read these numbers as conditional scenarios.</strong> Task shares and future savings are author assumptions. Changing the workload or assumptions changes every projection. The cited studies support mechanisms and context—not these exact future percentages. <a href="#methods">Audit the model.</a></div>
<div class="grid three"><article class="card"><div class="step-num">01 / WHAT CHANGES?</div><h3>Explore the task map</h3><p>Compare concepts, BIM, calculations, checking and site work across five horizons.</p><a href="#tasks">Open the heatmap →</a></article><article class="card"><div class="step-num">02 / WHAT ABOUT MY ROLE?</div><h3>Build your own workload</h3><p>Start with an illustrative role profile, then enter your actual weekly hours.</p><a href="#scenarios">Personalize the model →</a></article><article class="card"><div class="step-num">03 / WHAT SHOULD I LEARN?</div><h3>Prepare for changing work</h3><p>Turn the research into a practical learning and workflow-measurement plan.</p><a href="#career">Read the career playbook →</a></article></div>`;}
function visibleTasks(){let ts=D.tasks.filter(t=>(ui.taskTag==='All'||t.tag===ui.taskTag)&&(t.title+' '+t.items.join(' ')+' '+t.current+' '+t.future).toLowerCase().includes(ui.taskQuery.toLowerCase()));const r=estimate();if(ui.taskSort==='exposure')ts.sort((a,b)=>r.byTask.find(x=>x.id===b.id).removable-r.byTask.find(x=>x.id===a.id).removable);if(ui.taskSort==='hours')ts.sort((a,b)=>plan.hours[b.id]-plan.hours[a.id]);return ts;}
function tasks(){const ts=visibleTasks();return heading('TASK ATLAS / ENGINEERING + BIM','A whole job, made visible.','Inspect the evidence behind today’s workflows and the assumptions behind every future cell. Click any cell for task details and the calculation.')+`<div class="controls"><label class="search-field">Search tasks<input id="task-search" type="search" placeholder="Try Revit, RFI, framing or load path" value="${esc(ui.taskQuery)}"></label><label>Category<select id="task-tag">${['All','Engineering','BIM','Delivery','Field','Assurance'].map(x=>`<option ${x===ui.taskTag?'selected':''}>${x}</option>`).join('')}</select></label><label>Sort by<select id="task-sort">${[['workflow','Workflow order'],['exposure','Highest modeled reduction'],['hours','Most weekly hours']].map(([v,l])=>`<option value="${v}" ${ui.taskSort===v?'selected':''}>${l}</option>`).join('')}</select></label><span class="count">${ts.length} / 14 clusters</span></div>
<div class="card"><div class="section-head"><div><h2>How the work could change</h2><p>Today: type of evidence available · Future: modeled within-task gross hour reduction</p></div><label>Scenario<select id="task-scenario">${D.scenarios.map(s=>`<option value="${s.id}" ${s.id===plan.scenario?'selected':''}>${s.name}</option>`).join('')}</select></label></div><div class="table-wrap"><table class="heatmap"><thead><tr><th>Task cluster / current hours</th><th>2026<br>Evidence type</th>${D.horizons.slice(1).map(y=>`<th>${y}</th>`).join('')}</tr></thead><tbody>${ts.map(t=>`<tr><th scope="row">${esc(t.title)}<small>${t.tag} · ${plan.hours[t.id].toFixed(1)} h/week · ${t.items.length} tasks</small></th><td><button class="heat-cell heat-0 heat-current" data-task="${t.id}" data-year="0" aria-label="${esc(t.title)}: inspect current evidence">${t.evidenceLabel}</button></td>${D.horizons.slice(1).map((yr,i)=>{let b=estimate(plan.scenario,i+1).byTask.find(x=>x.id===t.id);return `<td><button class="heat-cell heat-${Math.min(5,Math.ceil(b.removable*5))}" data-task="${t.id}" data-year="${i+1}" aria-label="${esc(t.title)}, ${yr}: ${percent(b.removable)} gross modeled reduction">${percent(b.removable)}</button></td>`;}).join('')}</tr>`).join('')}</tbody><caption>Task taxonomy synthesized from role descriptions and guidance. Current evidence labels are editorial classifications, not a readiness score. Future cells show gross within-task model outputs before added project-level review; they are not observed automation rates. ${refs(['S02','S03','S04','S13'],true)}</caption></table></div>${ts.length?'':'<p class="empty">No matching tasks. Try another search or category.</p>'}<div class="heat-legend"><span>Lower modeled reduction</span>${[1,2,3,4,5].map(i=>`<i class="heat-${i}"></i>`).join('')}<span>Higher modeled reduction · percentages are printed in every cell</span></div></div>
<div class="notice"><strong>Gross task reduction is not net project saving.</strong> The model applies your task mix and subtracts added checking, integration and rework once at the project level. <a href="#scenarios">Edit your hours and assumptions.</a>${refs(['S13','S15'],true)}</div>`;}
function slider(id,label,value,min,max,step,display){return `<label><span class="range-label">${label}<output id="out-${id}">${display}</output></span><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></label>`;}
function hourFigure(r){const rows=[['Original work remaining',1-r.gross,'var(--muted)'],['Added checking / integration',r.overhead,'var(--scenario-fast)'],[r.net<0?'Net added hours':'Net hours released',Math.abs(r.net),'var(--accent)']];return `<figure><svg class="chart" viewBox="0 0 520 180" role="img" aria-label="Per 100 baseline hours: ${rows.map(([l,v])=>l+' '+(v*100).toFixed(1)).join('; ')}">${rows.map(([l,v,c],i)=>`<text x="0" y="${17+i*60}" fill="var(--muted)" font-size="12">${l}</text><rect x="0" y="${29+i*60}" width="430" height="7" rx="3" fill="var(--line)"/><rect x="0" y="${29+i*60}" width="${Math.min(1,v)*430}" height="7" rx="3" fill="${c}"/><text x="516" y="${36+i*60}" fill="var(--ink)" font-size="13" text-anchor="end">${(v*100).toFixed(1)}</text>`).join('')}</svg><figcaption>Hours per 100 baseline hours. ${percent(r.gross,true)} gross saving − ${percent(r.overhead,true)} added review = ${percent(r.net,true)} net. Existing review is already in the baseline. ${refs(['S13','S15'],true)}</figcaption></figure>`;}
function sensitivityRows(){const base=estimate().net,changes=[['Task potential −20%',{...options(),potentialScale:plan.potentialScale*.8}],['Task potential +20%',{...options(),potentialScale:plan.potentialScale*1.2}],['Realization −20%',{...options(),adoptionScale:plan.adoptionScale*.8}],['Added review +3 points',{...options(),overheadDelta:plan.overheadDelta+.03}],['Added review −3 points',{...options(),overheadDelta:plan.overheadDelta-.03}]];return changes.map(([name,opts])=>{let n=F.estimate(D,plan.scenario,plan.horizon,plan.hours,opts).net;return `<tr><th scope="row">${name}</th><td>${percent(n)}</td><td>${(100*(n-base)>=0?'+':'')+(100*(n-base)).toFixed(1)} pp</td></tr>`;}).join('');}
function lab(){const r=estimate(),e=range(),year=D.horizons[plan.horizon],years=year-2026,hours=totalHours(),newWork=years?plan.newWork/100:0,index=F.laborIndex(r.net,years,plan.growth/100,newWork),be=F.breakEven(r.net,years,newWork);
return heading('MY WORKLOAD / PERSONAL SCENARIO LAB','Make the assumptions yours.','Choose an illustrative role, enter your weekly task hours, and test how technology, review costs and demand change the result.')+scenarioButtons()+`<div class="workbench"><section class="card"><div class="section-head"><h2>Your inputs</h2>${badge('A01')}</div><div class="control-stack"><label>Role profile<select id="profile">${D.profiles.map(p=>`<option value="${p.id}" ${plan.profile===p.id?'selected':''}>${p.name}</option>`).join('')}<option value="custom" ${plan.profile==='custom'?'selected':''}>Custom workload</option></select></label><div class="form-row"><label>Horizon<select id="horizon">${D.horizons.map((y,i)=>`<option value="${i}" ${i===plan.horizon?'selected':''}>${y}${i?' / +'+(y-2026)+' years':' / baseline'}</option>`).join('')}</select></label><label>Weekly hours<input id="weekly-total" type="number" min="1" max="168" step="1" value="${hours.toFixed(1)}"></label></div><p class="compact full">${esc(D.profiles.find(p=>p.id===plan.profile)?.description||'Your own allocation across the 14 task clusters.')} Profiles are author assumptions, not surveyed time budgets.${refs(['S02','S03','S04'],true)}</p><details><summary>Technology & review assumptions</summary><div class="control-stack">${slider('potential-scale','Task potential multiplier',plan.potentialScale,.5,1.5,.05,plan.potentialScale.toFixed(2)+'×')}${slider('adoption-scale','Realization multiplier',plan.adoptionScale,.5,1.2,.05,plan.adoptionScale.toFixed(2)+'×')}${slider('overhead-delta','Extra review above this scenario',plan.overheadDelta,-.05,.15,.01,(plan.overheadDelta>=0?'+':'')+(plan.overheadDelta*100).toFixed(0)+' pp')}<p class="compact">Multipliers modify the selected scenario. Realization is capped at 100%; the per-task cap is 98%. Negative net savings are allowed.</p></div></details><details open><summary>Market & new work</summary><div class="control-stack"><label>Market preset<select id="market"><option value="custom">Current / custom</option value="flat">Flat demand · no new work</option><option value="growing">Growing services · 2%, 10% new work</option><option value="expansion">Demand expansion · 3%, 20% new work</option></select></label>${slider('growth','Annual service-output growth',plan.growth,-2,5,.1,plan.growth.toFixed(1)+'%')}${slider('new-work','New scope / assurance labor',plan.newWork,0,30,1,plan.newWork+'% of baseline')}<p class="compact">These are illustrative demand inputs, not BLS-calibrated employment predictions.</p></div></details><div class="full"><div class="snapshot-actions"><button id="share-plan">Share link</button><button id="export-plan">Export JSON</button><button id="import-plan">Import JSON</button><button id="print-plan">Print / Save PDF</button><button id="reset-plan">Reset all</button></div><input id="import-file" type="file" accept="application/json,.json" hidden><p class="compact" id="save-status" style="margin-top:13px">${loadNote||'Changes save automatically on this device when storage is available.'}</p></div></div></section>
<div><div class="result-banner"><span class="eyebrow">${esc(scenario().name.toUpperCase())} / ${year}</span><div style="margin-top:8px"><strong>${(Math.abs(r.net)*hours).toFixed(1)} equivalent hours ${r.net<0?'added':'released'}</strong> <span class="quiet">per ${hours.toFixed(1)}-hour baseline workload</span></div><p>Same scope and quality. This describes task labor, not a shorter contracted workweek or a personal employment prediction.</p>${refs(['S13','S15','S24'],true)}</div>
<div class="grid four"><div class="card metric-card featured"><div class="eyebrow">NET SAVING</div><div class="metric">${percent(r.net)}</div><div class="stat-note">Additional to 2026</div></div><div class="card metric-card"><div class="eyebrow">SENSITIVITY RANGE</div><div class="metric">${Math.round(e.low*100)}–${Math.round(e.high*100)}<small>%</small></div><div class="stat-note">Chosen assumptions, not probability</div></div><div class="card metric-card"><div class="eyebrow">LABOR DEMAND INDEX</div><div class="metric">${Math.round(index)}</div><div class="stat-note">2026 = 100; includes new work</div></div><div class="card metric-card"><div class="eyebrow">BREAK-EVEN GROWTH</div><div class="metric">${years?percent(be,true):'—'}</div><div class="stat-note">Annual output growth for index 100</div></div></div>${refs(['S01','S19','S24'],true)}
<div class="card block"><div class="section-head"><div><h2>Where the hours go</h2><p>Fixed-scope accounting · ${year}</p></div><button class="text-button" data-claim="range">Explain the sensitivity range →</button></div>${hourFigure(r)}</div>
<div class="card block"><div class="section-head"><div><h2>Your week, task by task</h2><p>Enter hours. The model normalizes them to your total workload.</p></div><span class="tag">${hours.toFixed(1)} h total</span></div><div class="table-wrap"><table class="workload-table"><thead><tr><th>Task cluster</th><th>Hours / week</th><th>Share</th><th>Gross reduction</th></tr></thead><tbody>${D.tasks.map((t,i)=>`<tr><th scope="row">${esc(t.title)}<div class="microbar"><span style="width:${r.byTask[i].weight*100}%"></span></div></th><td><input class="task-hours" data-task-hours="${t.id}" type="number" min="0" max="168" step="0.1" value="${plan.hours[t.id]}" aria-label="Weekly hours for ${esc(t.title)}"></td><td>${percent(r.byTask[i].weight)}</td><td>${percent(r.byTask[i].removable)}</td></tr>`).join('')}</tbody><caption>Hours are your inputs or an illustrative profile. Gross within-task reduction is modeled before the overall review deduction. ${refs(['S02','S03','S04'],true)}</caption></table></div></div>
<div class="card block"><h2>Which assumptions move the result?</h2><div class="table-wrap"><table class="sensitivity-table"><thead><tr><th>Change one input</th><th>Net saving</th><th>Change</th></tr></thead><tbody><tr><th scope="row">Selected case</th><td>${percent(r.net)}</td><td>—</td></tr>${sensitivityRows()}</tbody><caption>One-at-a-time sensitivity. The headline envelope combines potential ±20% with added review ∓3 percentage points. Other inputs stay fixed. Neither is a confidence interval. ${refs(['S13','S17'],true)}</caption></table></div></div>
<div class="notice"><strong>Less labor per project does not determine total employment.</strong> The labor index combines selected service-output growth with remaining task labor and new work. Wages, fees, capital costs and hiring decisions are outside this simplified model.${refs(['S01','S19','S24'],true)}</div></div></div>`;}
function timeline(){const t=D.timeline[plan.horizon];return heading('FUTURE SCENARIOS / 5, 10, 20 & 30 YEARS','Several futures. No scheduled destiny.','Compare the mechanisms that could change the profession. Confidence in timing and magnitude declines with the horizon.')+`<div class="horizon-bar"><div class="eyebrow">SELECT A HORIZON</div>${horizonTabs()}</div><article class="card"><div class="year-label">${t.year} / ${t.label}</div><h2>${t.title}</h2><span class="badge inference">${t.confidence}</span><p style="margin-top:16px">${t.body}</p><div class="grid two"><div><h3>BIM & documentation</h3><p>${t.bim}</p></div><div><h3>People & firms</h3><p>${t.labor}</p></div></div>${refs(t.refs,plan.horizon>0)}</article><div class="section-head block"><div><h2>What would each path require?</h2><p>The narrative above is a central-case synthesis. These are alternative conditional paths.</p></div></div><div class="timeline-grid">${D.scenarios.map((s,i)=>`<article class="card timeline-card ${plan.scenario===s.id?'selected':''}"><div class="year-label">0${i+1} / ${s.id==='setback'?'STRESS TEST':'CONDITIONAL PATH'}</div><h3>${s.name}</h3><div class="metric">${percent(estimate(s.id).net)}<small> modeled net saving</small></div><p>${s.story}</p><p><strong>Watch for:</strong> ${s.trigger}</p>${refs(s.refs,true)}<button data-scenario="${s.id}" style="margin-top:15px">Use this path</button></article>`).join('')}</div><div class="card block"><h2>Compare the trajectories</h2>${chartFigure()}${snapshotTable()}</div><div class="notice"><strong>Today is a baseline, not zero AI use.</strong> Zero in 2026 means no additional savings relative to the work and automation already included in that baseline. The setback scenario is an author-designed stress case; it does not claim that a particular safety event occurred.${refs(['S13','S15','S17'],true)}</div>`;}
const evidenceItems=[
 ['S20','~80%','Controlled iteration saving','Structural','The reported 2.5 → 0.5-day endpoints imply 80%. Arup states about 82%; the discrepancy is retained. Same model, loads and code; engineer review retained.'],
 ['S13','Use cases','Structural guidance','Structural','Lists applications across analysis, design, BIM and reporting. Guidance describes possibilities; it does not measure saved hours.'],
 ['S08','82–86%','Statics exam performance','Structural','Custom GPT exam scores. Not the accuracy of complete structural design or a current-frontier comparison.'],
 ['S09','26–50%','Structural benchmark pass rates','Structural','Selected 2025 model results in Table 2. Different models on a bounded benchmark, not improvement over time.'],
 ['S10','32%','Experimental BIM agent success','BIM','Architectural modeling through GUI use. This success measure is not structural model correctness.'],
 ['S11','+21%','BIM evaluation-score improvement','BIM','Domain tuning improved G-Eval over the base model. The score change is not a labor saving.'],
 ['S12','Version-specific','Revit authoring assistance','BIM','Vendor documentation describes selected authoring features in Revit 2027. It does not imply availability in Revit 2022–2025.'],
 ['S05','45% / 34%','No implementation / pilots','Adoption','RICS construction survey of over 2,200 responses. Broader than structural design-office use.'],
 ['S06','74%','Architecture practices using AI','Adoption','Use in at least some projects. Adjacent discipline; not audited productivity or full delivery automation.'],
 ['S01','+6%','Civil-engineer employment outlook','Work & demand','BLS projection for 2025–2035. A broad occupation forecast that does not isolate structural work or AI displacement.'],
 ['S16','+15%','Customer-support productivity','Work & demand','Published study of 5,172 support agents. A real-world result from a different profession; not a structural model input.'],
 ['S17','+19% time','Developers took longer with AI','Work & demand','Randomized study of 16 experienced developers and 246 tasks with early-2025 tools. Selected software work, not structural engineering.'],
 ['S14','43%','Digital processes in safety reports','Assurance','Share of a selected set of over 900 CROSS reports. Not an AI error rate or the probability of structural failure.'],
 ['S15','Responsibility','Professional policy position','Assurance','NCEES calls for retained professional responsibility and independent validation. This position is not itself every jurisdiction’s law.']
];
function evidence(){let list=evidenceItems.filter(x=>ui.evidenceFilter==='All'||x[3]===ui.evidenceFilter);return heading('EVIDENCE ROOM / FINDINGS & THEIR LIMITS','Read the finding. Check its reach.','Research, vendor features, occupational data and professional guidance answer different questions. Inspect the source before carrying a result into a projection.')+`<div class="controls"><label>Evidence area<select id="evidence-filter">${['All','Structural','BIM','Adoption','Work & demand','Assurance'].map(x=>`<option ${ui.evidenceFilter===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><span class="count">${list.length} findings · research snapshot 30 Sep 2026</span></div><div class="grid three">${list.map(([id,metric,title,area,note])=>{const s=source(id);return `<article class="card evidence-card"><div class="source-kind">${s.kind} / ${area}</div><div class="metric">${metric}</div><h3>${title}</h3><p>${note}</p><p class="scope"><strong>Scope:</strong> ${s.scope}</p><button class="text-button" data-source="${id}">Inspect finding, location & limits →</button>${refs([id])}</article>`;}).join('')}</div><div class="grid two block"><article class="card"><h2>The gap worth measuring</h2><p>This selected review did not establish representative whole-role structural-engineering savings. A useful next study would track complete comparable workflows, including setup, production, checking, correction and downstream rework.</p><p>This is a proposed measurement protocol, not an existing study.</p><button id="measurement-template">Download blank workflow log (CSV)</button>${refs(['S13','S15','S17'],true)}</article><article class="card"><h2>How to use the workflow log</h2><ol class="compact quiet"><li>Record an anonymized workflow and comparable scope.</li><li>Measure each stage with and without AI assistance.</li><li>Record reviewer acceptance, defects and rework.</li><li>Compare total time only where quality and scope are comparable.</li><li>Record tool version and measurement date.</li></ol>${refs(['S13','S15','S17'],true)}</article></div><div class="notice"><strong>Source access matters.</strong> Some papers were read through public abstracts and some vendor material through indexed official excerpts. Each source entry records the boundary. No confidence score is assigned merely because a citation exists.</div>`;}
const careers=[
 ['Build judgment you can demonstrate','Practice independent hand checks, load paths, stability, serviceability and detailing. Keep a record of why you accepted or rejected an automated output.',['S03','S08','S13','S15']],
 ['Own the model and its meaning','Learn parameters, physical versus analytical models, data exchange, change tracking and repeatable model QA. Model completeness and solver convergence are different checks.',['S03','S12','S13','S18']],
 ['Measure one complete workflow','Start with a bounded task such as document comparison or drawing production. Include setup, checking and corrections when judging whether automation helped.',['S13','S15','S17']],
 ['Protect the learning pathway','If production tasks shrink, deliberately retain calculation practice, model building, detailing, mentoring and site exposure. This is a preparation recommendation, not a measured training forecast.',['S03','S04','S13','S15']],
 ['Broaden field and client experience','Seek existing-condition assessment, construction administration and multidisciplinary decisions. These expand the task mix beyond digital production; they are not guarantees against future automation.',['S02','S03','S13']],
 ['Watch the business model','Track project fees, output per team, review bottlenecks and new services. Fewer hours per deliverable may change margins, prices or capacity; employment depends on more than technical capability.',['S01','S05','S19','S24']]
];
function career(){return heading('CAREER PLAYBOOK / TURN THE RESEARCH INTO PRACTICE','Prepare for the work that changes.','These are author recommendations grounded in the role taxonomy and evidence. They describe ways to build capability, not promises that any specialization is immune.')+`<div class="grid three">${careers.map(([title,body,ids],i)=>`<article class="card career-card"><div class="step-num">0${i+1} / PREPARATION</div><h3>${title}</h3><p>${body}</p>${refs(ids,true)}</article>`).join('')}</div><div class="card block"><h2>A practical 90-day experiment</h2><div class="grid three"><div><div class="step-num">DAYS 01–30</div><h3>Map your actual work</h3><p>Record task hours and review burden for a normal workload. Replace the illustrative profile in the lab with those observations.</p><a href="#scenarios">Build a workload →</a></div><div><div class="step-num">DAYS 31–60</div><h3>Run a bounded comparison</h3><p>Use an approved tool on comparable work. Record quality, correction and review time, not only first-draft speed.</p><a href="#evidence">Get the measurement template →</a></div><div><div class="step-num">DAYS 61–90</div><h3>Keep what survives review</h3><p>Document acceptance criteria, failure cases and total time. Revisit the assumptions using the measured evidence.</p><a href="#methods">Audit assumptions →</a></div></div>${refs(['S03','S13','S15','S17'],true)}</div><div class="notice"><strong>Signals to watch:</strong> audited hours for whole projects; quality and rework; junior hiring and training; fees versus delivered output; and accepted assurance practices. These are proposed indicators, not measured trends.${refs(['S05','S13','S15','S17'],true)}</div>`;}
function methods(){return heading('METHODS / A01 VERSION 2','The assumptions are part of the result.','This is a transparent scenario calculator around a curated research review. It is not a statistically fitted forecast of automation or employment.')+`<div class="grid two"><article class="card"><h2>1. Model a complete workload</h2><p>Enter weekly task hours or choose an illustrative profile. Normalize them to task weights, then apply task potentials, scenario capability and realized adoption.</p><div class="formula">gross = Σ wᵢ × min(0.98, pᵢ,t × cₛ,t × P) × min(1, aₛ,t × A)<br>net saving = gross − clip(hₛ,t + H, 0, 0.50)</div><dl class="term-list"><dt>w</dt><dd>Task hours divided by total selected hours.</dd><dt>p</dt><dd>Assumed task potential at each future horizon.</dd><dt>c, a, h</dt><dd>Scenario capability, realization and additional review overhead.</dd><dt>P, A, H</dt><dd>Your potential multiplier, realization multiplier and extra-review adjustment.</dd></dl><p class="compact">At the 2026 baseline all additional savings and added overhead equal zero. Existing automation and routine review are already included. Negative net savings mean the selected workflow requires more labor.</p>${refs(['S02','S03','S13','S15'],true)}</article><article class="card"><h2>2. Stress the assumptions</h2><p>${D.method.sensitivity}</p><div class="formula">lower = model(P × 0.8, H + 0.03)<br>upper = model(P × 1.2, H − 0.03)</div><p>The chosen bounds are the same at every horizon for interpretability. They do not claim uncertainty stays constant over time. Long-horizon structural and institutional uncertainty is not quantified by this envelope.</p><p><strong>No scenario probabilities are assigned.</strong> The setback branch is an invented stress test, not a prediction of a particular event.</p>${refs(['S05','S14','S15','S17'],true)}</article></div>
<div class="card block"><h2>3. Keep labor demand distinct from task savings</h2><div class="formula">labor demand index = 100 × (1 + g)ᵀ × (1 − net saving + n)<br>break-even g = [1 / (1 − net saving + n)]^(1/T) − 1</div><p>g is annual engineering-service output growth; T is years since 2026; n is new scope/assurance labor per project relative to baseline labor. At T = 0, n = 0. This constant-mix accounting model omits wages, fees, capital, demand feedback and firm hiring decisions. Default 2% growth and 10% new work are assumptions, not a calibration to BLS.</p>${refs(['S01','S19','S24'],true)}</div>
<details class="card block"><summary>Inspect every base scenario parameter</summary><div class="table-wrap"><table class="assumption-table"><thead><tr><th>Scenario</th><th>Year</th><th>Capability c</th><th>Realization a</th><th>Added review h</th></tr></thead><tbody>${D.scenarios.map(s=>D.horizons.slice(1).map((y,i)=>`<tr><th scope="row">${s.name}</th><td>${y}</td><td>${s.capability[i+1].toFixed(2)}</td><td>${s.adoption[i+1].toFixed(2)}</td><td>${percent(s.overhead[i+1],true)}</td></tr>`).join('')).join('')}</tbody><caption>Author inputs before user adjustments. Decreasing capability multipliers in some paths discount the increasing task potentials; they do not claim model capability declines. None of these exact multipliers is measured by the cited sources.${refs(['S05','S09','S13','S15','S20'],true)}</caption></table></div></details>
<details class="card block"><summary>Inspect baseline task potentials and workload profiles</summary><div class="table-wrap"><table class="assumption-table"><thead><tr><th>Task</th><th>Baseline share</th>${D.horizons.slice(1).map(y=>`<th>p / ${y}</th>`).join('')}</tr></thead><tbody>${D.tasks.map(t=>`<tr><th scope="row">${t.title}</th><td>${t.weight}%</td>${t.potential.map(v=>`<td>${v}%</td>`).join('')}</tr>`).join('')}</tbody><caption>Fixed A01 task inputs. Baseline team weights are assumed, not a time-use survey. Role presets are editable alternative allocations; the canonical JSON contains every preset. ${refs(['S02','S03','S04','S13'],true)}</caption></table></div></details>
<div class="grid two block"><article class="card"><h2>Research protocol</h2><p>Curated review conducted on 30 September 2026. Sources include official occupational data, employer role descriptions, structural/BIM studies, professional policy, documented deployments and adjacent-domain productivity research.</p><p>Full accessible pages/tables were used where available; specified papers use public abstracts and some vendor material uses indexed official excerpts. Source entries identify limits and locations. This was not a systematic meta-analysis.</p><p>Dashboard v2, published 1 October 2026, adds role profiles, an assumption envelope and a setback stress case. It does not claim a new research review or refreshed source access dates.</p>${refs(['S02','S03','S13','S24'])}</article><article class="card"><h2>What this model leaves out</h2><ul class="compact">${D.method.limits.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${refs(['S05','S13','S15','S17'],true)}</article></div><div class="card block"><h2>Reproducibility & local privacy</h2><p>All model inputs and calculations run in your browser. Saving uses this device’s browser storage; shared links contain the workload values and assumptions. Avoid entering private project identifiers. JSON exports include the research date, model version and complete inputs. No account or server is required.</p><p>Static HTML, CSS and JavaScript keep the site easy to audit and publish on GitHub Pages. The source repository includes validation tests and a deployment workflow.</p><a href="https://github.com/Isaiah-Narvaez-42/structural-engineering-ai">View the repository ↗</a>${refs(['S23'])}</div>`;}
function sourceCard(s){return `<article class="card source-card" id="ref-${s.id}"><div class="source-top"><div><span class="source-id">${s.id}</span> <span class="tag">${s.kind}</span><h3>${s.title}</h3></div><a class="source-open" href="${s.url}" target="_blank" rel="noopener noreferrer">Open original ↗</a></div><div class="source-meta">${s.author} · ${s.date}<br>Read ${s.accessed} · ${s.locator}</div><p><b>Finding used:</b> ${s.finding}</p><p><b>Scope:</b> ${s.scope}</p><p><b>Boundary:</b> ${s.limitation}</p>${s.id==='S12'?'<p class="compact">Supplementary official support entries: <a href="https://www.autodesk.com/support/technical/article/caas/sfdcarticles/sfdcarticles/How-to-enable-Autodesk-Assistant-in-Revit.html" target="_blank" rel="noopener">Availability</a> · <a href="https://www.autodesk.com/support/technical/article/caas/sfdcarticles/sfdcarticles/What-AI-features-are-available-in-Revit.html" target="_blank" rel="noopener">AI features</a>.</p>':''}</article>`;}
function references(){const sources=D.sources.filter(s=>(ui.sourceKind==='All'||ui.sourceKind===s.kind)&&(s.id+' '+s.title+' '+s.author+' '+s.finding).toLowerCase().includes(ui.sourceQuery.toLowerCase()));return heading('SOURCE REGISTER / 24 TRACEABLE REFERENCES','Follow every claim to its source.','Find the underlying finding, scope, location and limitation. A01 is the author’s model; research sources do not validate its exact future percentages.')+`<div class="controls"><label class="search-field">Find a source<input id="source-search" type="search" placeholder="Search author, title, finding or source ID" value="${esc(ui.sourceQuery)}"></label><label>Source type<select id="source-kind">${['All',...new Set(D.sources.map(s=>s.kind))].map(k=>`<option ${ui.sourceKind===k?'selected':''}>${k}</option>`).join('')}</select></label><span class="count">${sources.length} entries</span></div>${sources.map(sourceCard).join('')}${sources.length?'':'<p class="empty">No matching sources. Try a broader search.</p>'}`;}
function sourceNote(s){return `<section class="dialog-source"><span class="source-id">${s.id}</span> <span class="tag">${s.kind}</span><h3 style="margin-top:10px">${s.title}</h3><div class="source-meta">${s.author} · ${s.date}<br>Location: ${s.locator} · Read ${s.accessed}</div><p><strong>Finding used — paraphrase:</strong> ${s.finding}</p><p><strong>Scope:</strong> ${s.scope}</p><p><strong>What it does not establish:</strong> ${s.limitation}</p><a href="${s.url}" target="_blank" rel="noopener noreferrer">Read the original ↗</a> · <a href="#references/${s.id}" data-close>Full reference entry</a></section>`;}
function openDialog(kicker,title,html){lastFocus=document.activeElement;$('#dialog-kicker').textContent=kicker;$('#dialog-content').innerHTML=`<h2 id="dialog-title" tabindex="-1">${title}</h2>${html}`;const dialog=$('#detail-dialog');if(!dialog.open)dialog.showModal();dialog.scrollTop=0;$('#dialog-title').focus({preventScroll:true});}
function inspectTask(id,h){const t=D.tasks.find(t=>t.id===id);if(!t)return;const r=estimate(plan.scenario,h),b=r.byTask.find(x=>x.id===id),s=scenario();openDialog('TASK DETAIL / '+D.horizons[h],esc(t.title),`<div class="detail-grid"><div><span class="tag">${t.tag} / ${t.items.length} task examples</span><h3 style="margin-top:18px">What this cluster includes</h3><ul>${t.items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Current use</h3><p>${t.current}</p><p class="compact"><b>Evidence classification:</b> ${t.evidenceLabel}. ${t.evidenceNote}</p></div><div>${h?`<span class="badge assumption">${D.horizons[h]} / ${s.name}</span><div class="detail-metric">${percent(b.removable)} gross reduction</div><p>Modeled within this task; additional project-level review has not been deducted.</p><div class="formula">min(98%, ${t.potential[h-1]}% × ${s.capability[h]} × ${plan.potentialScale.toFixed(2)})<br>× min(100%, ${percent(s.adoption[h])} × ${plan.adoptionScale.toFixed(2)})<br>= ${percent(b.removable,true)}</div><h3>Projected direction — inference</h3><p>${t.future}</p>`:'<h3>2026 baseline</h3><p>Existing automation is included in the baseline. No percentage of today’s work automated by AI is estimated here.</p>'}<h3>Human decision / accountability</h3><p>${t.human}</p><p><strong>Your workload:</strong> ${plan.hours[id].toFixed(1)} hours / ${percent(b.weight)} of selected baseline.</p>${refs([],true)}</div></div><h3 style="margin-top:24px">Evidence behind the task context</h3><p class="compact">These sources support the role, possible use or current boundary. They do not measure the future percentage above.</p>${t.refs.map(id=>sourceNote(source(id))).join('')}`);}
function inspectClaim(id){if(id==='range'){openDialog('A01 / ASSUMPTION SENSITIVITY','What this range means',`<p>${D.method.sensitivity}</p><div class="formula">Selected case: ${percent(estimate().net,true)}<br>Lower stress result: ${percent(range().low,true)}<br>Upper stress result: ${percent(range().high,true)}</div><p>There is no assigned probability of landing inside this range. The endpoints are chosen stress conditions, not estimates derived from study sampling.</p><a href="#methods" data-close>Inspect the complete method →</a>`);}else openDialog('SYNTHESIS / AUTHOR INFERENCE','Why expect the work mix to change?',`<p>The role descriptions show a mix of production, judgment, coordination and responsibility. Structural guidance and bounded demonstrations suggest some digital production can be assisted. Professional policy retains review responsibilities today. The inference is a change in task mix; it does not establish a particular staffing outcome.</p><p><strong>What could weaken this conclusion?</strong> Full-workflow trials showing that checking and integration eliminate the savings, slow adoption, or demand and new work that absorb capacity differently.</p>${['S03','S13','S15','S24'].map(id=>sourceNote(source(id))).join('')}`);}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function save(){try{F.validateSnapshot(D,plan);localStorage.setItem(storageKey,JSON.stringify(plan));loadNote='Saved on this device.';}catch{loadNote='Browser storage is unavailable. Export JSON to keep this scenario.';}const u=new URL(location.href);if(u.searchParams.has('plan')){u.searchParams.set('plan',JSON.stringify(plan));history.replaceState(null,'',u);} }
function rerender(focus){const before=scrollY,opened=$$('details').map(el=>el.open);render(true);$$('details').forEach((el,i)=>{if(i<opened.length)el.open=opened[i];});scrollTo(0,before);if(focus){const el=$(focus);el?.focus({preventScroll:true});}}
function change(values,focus){Object.assign(plan,values);save();rerender(focus);}
function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function snapshot(){return {...plan,researchAsOf:D.asOf,model:'A01 v2',exportedAt:new Date().toISOString(),notice:'Conditional author assumptions, not measured automation or a job-loss forecast.'};}
function printReport(){const r=estimate(),e=range(),year=D.horizons[plan.horizon],years=year-2026;$('#print-report').innerHTML=`<h1>Structural Futures / personal scenario report</h1><p>Generated ${new Date().toISOString().slice(0,10)} · Evidence snapshot ${D.asOf} · Model A01 v2</p><p>${esc(profileName())} · ${esc(scenario().name)} · ${year} · ${totalHours().toFixed(1)} baseline hours</p><div class="card"><h2>Conditional result</h2><p>Net additional labor saving: <strong>${percent(r.net,true)}</strong>. Equivalent hours ${r.net<0?'added':'released'}: ${(Math.abs(r.net)*totalHours()).toFixed(1)}. Chosen sensitivity range: ${percent(e.low,true)} to ${percent(e.high,true)}. Labor-demand index: ${F.laborIndex(r.net,years,plan.growth/100,years?plan.newWork/100:0).toFixed(1)}.</p><p>These values are calculations from author/user assumptions, not measured forecasts or probabilities. Task savings do not determine actual employment.</p>${refs(['S13','S15','S24'],true)}</div><h2>Inputs and method</h2><p>Potential multiplier ${plan.potentialScale}; realization multiplier ${plan.adoptionScale}; added-review adjustment ${(plan.overheadDelta*100).toFixed(1)} percentage points. Annual output growth ${plan.growth}%; new-work labor ${plan.newWork}% of baseline (zero at 2026).</p><p>Gross = Σ normalized task hours × min(0.98, potential × scenario capability × user potential multiplier) × min(1, scenario realization × user realization multiplier). Net = gross − added review. Labor index = 100 × (1 + growth)^years × (1 − net + new work).</p><p>${D.method.sensitivity}</p><table><thead><tr><th>Task</th><th>Baseline hours</th><th>Share</th><th>Gross modeled reduction</th><th>Context sources</th></tr></thead><tbody>${D.tasks.map((t,i)=>`<tr><th scope="row">${t.title}</th><td>${plan.hours[t.id].toFixed(2)}</td><td>${percent(r.byTask[i].weight,true)}</td><td>${percent(r.byTask[i].removable,true)}</td><td>${t.refs.join(', ')}</td></tr>`).join('')}</tbody><caption>A01 author/user task allocation and future inputs. Evidence supports context, not percentages.</caption></table><h2>All scenario paths</h2><table><thead><tr><th>Scenario</th>${D.horizons.map(y=>`<th>${y}</th>`).join('')}</tr></thead><tbody>${D.scenarios.map(s=>`<tr><th scope="row">${s.name}</th>${D.horizons.map((_,i)=>`<td>${percent(estimate(s.id,i).net,true)}</td>`).join('')}</tr>`).join('')}</tbody><caption>A01 conditional net savings; selected workload and user modifiers. Context: S05, S13, S15, S17, S20.</caption></table><h2>Limits</h2><ul>${D.method.limits.map(x=>`<li>${x}</li>`).join('')}</ul><h2 class="print-new-page">Source register</h2><div class="print-sources">${D.sources.map(s=>`<article id="print-${s.id}"><strong>${s.id} · ${s.title}</strong><br>${s.author} · ${s.date} · Read ${s.accessed}<br>Finding: ${s.finding}<br>Scope: ${s.scope}<br>Limit: ${s.limitation}<br>Location: ${s.locator}<br><a href="${s.url}">${s.url}</a></article>`).join('')}</div>`;window.print();}
const views={overview,tasks,scenarios:lab,timeline,evidence,career,methods,references};
function render(keepScroll=false){let [view,id]=(location.hash.slice(1)||'overview').split('/');if(!views[view])view='overview';if(view==='references'&&id){ui.sourceQuery='';ui.sourceKind='All';}$('#content').innerHTML=views[view]();$$('nav a').forEach(a=>{let active=a.hash==='#'+view;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.title=({overview:'Overview',tasks:'Task Atlas',scenarios:'My Workload',timeline:'Future Scenarios',evidence:'Evidence Room',career:'Career Playbook',methods:'Methods',references:'References'}[view])+' — Structural Futures';bind(view);if(!keepScroll){scrollTo(0,0);if(view==='references'&&id){const el=document.getElementById('ref-'+id);el?.classList.add('highlight');el?.scrollIntoView({block:'start'});}}}
function bind(view){
 const filter=(selector,key)=>{const el=$(selector);if(el)el.addEventListener('input',()=>{const pos=el.selectionStart;ui[key]=el.value;rerender(selector);if(pos!=null)$(selector)?.setSelectionRange(pos,pos);});};
 if(view==='tasks'){filter('#task-search','taskQuery');$('#task-tag').onchange=e=>{ui.taskTag=e.target.value;rerender('#task-tag');};$('#task-sort').onchange=e=>{ui.taskSort=e.target.value;rerender('#task-sort');};$('#task-scenario').onchange=e=>change({scenario:e.target.value},'#task-scenario');}
 if(view==='references'){filter('#source-search','sourceQuery');$('#source-kind').onchange=e=>{ui.sourceKind=e.target.value;if(location.hash.includes('/'))history.replaceState(null,'','#references');rerender('#source-kind');};$('#source-search').addEventListener('input',()=>{if(location.hash.includes('/'))history.replaceState(null,'','#references');});}
 if(view==='evidence'){$('#evidence-filter').onchange=e=>{ui.evidenceFilter=e.target.value;rerender('#evidence-filter');};$('#measurement-template').onclick=()=>download('structural-workflow-measurement-template.csv','anonymous_workflow_id,measurement_date,project_type,task_cluster,scope_description,tool_and_version,method_conventional_or_ai,setup_hours,production_hours,review_hours,correction_hours,downstream_rework_hours,reviewer_accepted,defects_found,scope_and_quality_comparable,notes\n','text/csv');}
 if(view==='scenarios'){
 $('#profile').onchange=e=>{const id=e.target.value;change({profile:id,...(id!=='custom'?{hours:F.profileHours(D,id,totalHours())}:{})},'#profile');};
 $('#horizon').onchange=e=>change({horizon:Number(e.target.value)},'#horizon');
 $('#weekly-total').onchange=e=>{const value=Number(e.target.value);if(!Number.isFinite(value)||value<1||value>168){toast('Enter total weekly hours between 1 and 168.');rerender('#weekly-total');return;}const hours=F.allocateHours(D.tasks,D.tasks.map(t=>plan.hours[t.id]),value);change({hours},'#weekly-total');};
 const ranges=[['potential-scale','potentialScale',v=>v.toFixed(2)+'×'],['adoption-scale','adoptionScale',v=>v.toFixed(2)+'×'],['overhead-delta','overheadDelta',v=>(v>=0?'+':'')+(v*100).toFixed(0)+' pp'],['growth','growth',v=>v.toFixed(1)+'%'],['new-work','newWork',v=>v+'% of baseline']];
 ranges.forEach(([id,key,format])=>{const el=$('#'+id);el.oninput=()=>{$('#out-'+id).textContent=format(Number(el.value));};el.onchange=()=>change({[key]:Number(el.value)},'#'+id);});
 $('#market').onchange=e=>{const values={flat:{growth:0,newWork:0},growing:{growth:2,newWork:10},expansion:{growth:3,newWork:20}};if(values[e.target.value])change(values[e.target.value],'#market');};
 $$('.task-hours').forEach(el=>el.onchange=()=>{const id=el.dataset.taskHours,value=Number(el.value),hours={...plan.hours,[id]:value};try{F.validateSnapshot(D,{...plan,hours});change({hours,profile:'custom'},`[data-task-hours="${id}"]`);}catch(error){toast(error.message);rerender(`[data-task-hours="${id}"]`);}});
 $('#reset-plan').onclick=()=>{plan=F.baseline(D);save();rerender('#reset-plan');toast('Baseline assumptions restored.');};
 $('#export-plan').onclick=()=>download('structural-futures-scenario-v2.json',JSON.stringify(snapshot(),null,2),'application/json');
 $('#share-plan').onclick=async()=>{const url=new URL(location.href);url.searchParams.delete('v');url.searchParams.set('plan',JSON.stringify(plan));url.hash='scenarios';try{await navigator.clipboard.writeText(url.toString());toast('Scenario link copied. It includes these workload assumptions.');}catch{openDialog('SHARE SCENARIO','Copy your scenario link',`<p>This link contains task hours and model assumptions. Anyone with the link can restore them.</p><textarea class="readonly-link" id="share-url" readonly aria-label="Scenario link">${esc(url.toString())}</textarea>`);$('#share-url').select();}};
 $('#import-plan').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>65536)throw Error('Choose a scenario JSON smaller than 64 KB.');plan=F.validateSnapshot(D,JSON.parse(await file.text()));save();rerender('#import-plan');toast('Scenario imported and saved on this device.');}catch(error){toast(error instanceof SyntaxError?'That file is not valid JSON.':error.message);e.target.value='';}};
 $('#print-plan').onclick=printReport;
 }
}
function closeNav(){document.body.classList.remove('nav-open');$('#nav-backdrop').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-label','Open navigation');}
$('#menu-toggle').onclick=()=>{const open=document.body.classList.toggle('nav-open');$('#nav-backdrop').hidden=!open;$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation');};$('#nav-backdrop').onclick=closeNav;
$('#close-dialog').onclick=()=>$('#detail-dialog').close();$('#detail-dialog').addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true});});$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
document.addEventListener('click',e=>{const target=e.target.closest('[data-source],[data-task],[data-claim],[data-horizon],[data-scenario],[data-point],[data-close]');if(!target)return;
 if(target.hasAttribute('data-source')){e.preventDefault();const s=source(target.dataset.source);if(s)openDialog('SOURCE / '+s.id,esc(s.title),sourceNote(s));}
 else if(target.hasAttribute('data-task'))inspectTask(target.dataset.task,Number(target.dataset.year));
 else if(target.hasAttribute('data-claim'))inspectClaim(target.dataset.claim);
 else if(target.hasAttribute('data-horizon'))change({horizon:Number(target.dataset.horizon)},`[data-horizon="${target.dataset.horizon}"]`);
 else if(target.hasAttribute('data-scenario'))change({scenario:target.dataset.scenario},`[data-scenario="${target.dataset.scenario}"]`);
 else if(target.hasAttribute('data-point')){const [id,h]=target.dataset.point.split(',');const s=D.scenarios.find(s=>s.id===id);$('#chart-note').innerHTML=`${esc(s.name)} · <b>${D.horizons[Number(h)]}: ${percent(estimate(id,Number(h)).net,true)}</b> net additional hours removed · A01 author assumptions.`;}
 else if(target.hasAttribute('data-close')){$('#detail-dialog').close();if(target.hash===location.hash)render();}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNav();const point=e.target.closest('[data-point]');if(point&&(e.key==='Enter'||e.key===' ')){e.preventDefault();point.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
$('#theme').onclick=()=>{const light=document.body.classList.toggle('light');$('#theme').setAttribute('aria-label','Switch to '+(light?'dark':'light')+' theme');try{localStorage.setItem('structural-futures-theme',light?'light':'dark');}catch{}};
try{if(localStorage.getItem('structural-futures-theme')==='light'){document.body.classList.add('light');$('#theme').setAttribute('aria-label','Switch to dark theme');}}catch{}
window.addEventListener('hashchange',()=>{closeNav();if($('#detail-dialog').open)$('#detail-dialog').close();render();$('#main').focus({preventScroll:true});});render();
